# SQLite Campaign Draft Store

Below is a complete, runnable implementation using only the Python standard library. It provides a `CampaignDraftStore` with create/get/list/update, idempotency keys, explicit transactions, validation, optimistic version checks, and rollback. Tests cover duplicate requests, conflicting updates, pagination, and transaction failure.

## `campaign_store.py`

```python
import sqlite3
import json
import uuid
from datetime import datetime, timezone
from typing import Optional, List, Dict, Any

SCHEMA = """
CREATE TABLE IF NOT EXISTS campaign_drafts (
    id TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    status TEXT NOT NULL,
    budget INTEGER NOT NULL,
    version INTEGER NOT NULL DEFAULT 1,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS idempotency_keys (
    key TEXT PRIMARY KEY,
    operation TEXT NOT NULL,
    resource_id TEXT NOT NULL,
    response TEXT NOT NULL,
    created_at TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_drafts_created ON campaign_drafts(created_at, id);
"""

VALID_STATUSES = {"draft", "active", "paused", "archived"}


class ValidationError(ValueError):
    pass


class ConflictError(RuntimeError):
    pass


class NotFoundError(LookupError):
    pass


def _now() -> str:
    return datetime.now(timezone.utc).isoformat()


def _validate_name(name: Any) -> str:
    if not isinstance(name, str) or not name.strip():
        raise ValidationError("name must be a non-empty string")
    if len(name) > 200:
        raise ValidationError("name must be <= 200 chars")
    return name.strip()


def _validate_status(status: Any) -> str:
    if status not in VALID_STATUSES:
        raise ValidationError(f"status must be one of {sorted(VALID_STATUSES)}")
    return status


def _validate_budget(budget: Any) -> int:
    if isinstance(budget, bool) or not isinstance(budget, int):
        raise ValidationError("budget must be an integer")
    if budget < 0 or budget > 10_000_000:
        raise ValidationError("budget must be between 0 and 10,000,000")
    return budget


